  "plans.perMonthShort": "/tháng",
  "plans.included": "Đã bao gồm",
  "plans.notIncluded": "Không bao gồm",
  "plans.mobileIncludedNote": "Cả hai gói trên trang web đều bao gồm ứng dụng di động đi kèm, vì vậy người đăng ký trên trang web không bao giờ phải trả thêm phí di động hàng tháng.",
  "plans.priceNote": "Essentials là $14.99/tháng cộng thêm thuế áp dụng, nếu có. Business là $29.99/tháng cộng thêm thuế áp dụng, nếu có. Mọi khoản thuế bắt buộc được xác định trong quá trình thanh toán của nhà cung cấp và phải xuất hiện trong tổng số cuối cùng trước khi thanh toán. Trang so sánh này không phải là báo giá thuế hay ủy quyền thanh toán.",
  "plans.mobilePriceNote": "Gói chỉ dành cho di động là $4.99/tháng theo giá cơ sở dự kiến tại Hoa Kỳ. App Store hoặc Google Play hiển thị giá đăng ký thực tế tại địa phương và mọi khoản thuế áp dụng trước khi mua. Hạn mức sản phẩm, địa điểm và nhân viên của gói được đặt khi ra mắt, tách biệt với các gói trên trang web.",
  "plans.planChangeNote": "Việc thay đổi gói trên trang web phải được nhà cung cấp thanh toán xác nhận. Giá mới, ngày có hiệu lực và mọi khoản điều chỉnh theo tỷ lệ sẽ được giải thích trước khi thay đổi được ủy quyền. Việc nâng cấp không nên tạo ra một đăng ký thứ hai.",
  "plans.providerNote": "Giá, khoản phí và bản dùng thử được xử lý bởi nhà cung cấp mà bạn đăng ký qua đó — App Store, Google Play, trang web hoặc Shopify — không bao giờ bởi trang này.",
