  "valuation.footnote": "Giá trị chi phí dùng chi phí đơn vị hiện tại của mỗi sản phẩm, vì vậy việc nhập kho với giá mới sẽ định giá lại toàn bộ kệ hàng. Các đơn vị đang giữ vẫn được tính ở đây — chúng đang có mặt, chỉ là đã hứa cho một đơn hàng. Tiền bị thiếu không bao giờ được coi là 0; hãy để trống một trường cho đến khi biết con số.",
