  "print.pickOrderHint": "Hãy chọn một đơn đặt hàng mua từ danh sách để xem trước tài liệu.",
  "print.pickCustomerOrderHint": "Hãy chọn một đơn hàng khách hàng từ danh sách để xem trước tài liệu.",
  "print.pickReturnHint": "Hãy chọn một lần trả hàng đã ghi từ danh sách để xem trước tài liệu.",
  "print.chooseStyleHint": "Chọn một kiểu, rồi chọn sản phẩm từ danh sách. Bản xem trước hiển thị chính xác những gì sẽ ra khỏi máy in.",
  "print.howToReach": "Cách tiếp cận máy in của bạn",
  "print.howIntro": "Ứng dụng này kết nối với các máy in bạn đã sở hữu — bản thân nó không phải là máy in. Có bốn cách để tiếp cận một máy in, và nhãn in được trên cả hai gói qua bất kỳ cách nào. Phiếu đóng gói, đơn đặt hàng mua, chứng từ nhà cung cấp và báo cáo chỉ dành cho Business, bất kể kết nối nào.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Từ trang này, trên Chrome hoặc Edge trên máy tính để bàn và trên Chrome Android: chọn máy in nhãn của bạn và nhãn sẽ đi thẳng tới nó. Nó không hoạt động trong Safari trên iOS — trên iPhone, in Bluetooth đi kèm với ứng dụng di động. Một máy in chỉ nói ngôn ngữ Zebra ZPL hoặc ngôn ngữ riêng của Brother sẽ không hiểu các nhãn trang này gửi; điều đó được kiểm tra trên máy in thật trước khi được gọi là hoạt động.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Cài đặt máy in trên Wi-Fi của cửa hàng bạn, rồi dùng nút In — nó in qua máy in đã cài trên máy tính này, qua mạng của cửa hàng. Trên iPhone, AirPrint được tích hợp sẵn: một máy in AirPrint trên cùng Wi-Fi sẽ xuất hiện ngay trong trang in, không cần dây và không cần ứng dụng, và ứng dụng không cần mã riêng cho AirPrint. Máy in phải hỗ trợ AirPrint (hầu hết máy in mới đều có) và điện thoại cùng máy in phải ở trên cùng một Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Nối máy in vào mạng cửa hàng bằng dây Ethernet, cài đặt nó trên máy tính, và in qua nút In. Ethernet là đường dành cho máy tính để bàn và máy tính — iPhone không dùng dây Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Cắm máy in vào máy tính bằng dây của nó và dùng nút In — nó in qua máy in đã cài ở đó. Trên điện thoại Android với cáp USB OTG, nút USB ở trên sẽ nói chuyện thẳng với máy in. iPhone không thể in qua USB trực tiếp — không có WebUSB ở đó — vì vậy hãy dùng Wi-Fi / AirPrint, hoặc Bluetooth từ ứng dụng di động.",
  "print.howCordsLead": "Dây vẫn phục vụ iPhone, cách một bước.",
  "print.howCordsBody": "Một máy in USB cắm vào máy tính của cửa hàng, hoặc một máy in Ethernet nối dây vào mạng, sẽ xuất hiện trên iPhone của bạn qua Wi-Fi của cửa hàng (AirPrint / máy in dùng chung) — dây đưa máy in lên mạng một cách vững chắc, và điện thoại tiếp cận nó không dây.",
  "print.howOfflineLead": "Nếu internet bị mất,",
  "print.howOfflineBody": "các nhãn và tài liệu đã có trên trang này vẫn in được — nút In, PDF nhãn, Bluetooth và USB không cần kết nối. Thứ cần internet là việc tải trang và sản phẩm của nó ngay từ đầu. Chế độ ngoại tuyến đầy đủ (làm việc trong ứng dụng mà không có kết nối nào) là một bản dựng riêng, lớn hơn và không được khẳng định ở đây.",
