  "settings.cancelSubscription": "Hủy đăng ký",
  "settings.cancelTerms.appleLink": "Hướng dẫn hủy của Apple",
  "settings.cancelTerms.googlePlayLink": "Hướng dẫn hủy của Google Play",
  "settings.cancelTerms.graceTitle": "Sau khi kỳ đã thanh toán của bạn kết thúc — 15 ngày gia hạn, sau đó sẽ xóa:",
  "settings.cancelTerms.intro": "Đây là các điều khoản cho đăng ký Luminous StockHaven trả phí. Thanh toán đăng ký trên trang web được thực hiện qua Stripe. Bạn có thể tự hủy đăng ký bất cứ lúc nào bằng nút Hủy đăng ký bên dưới — không cần nhân viên phê duyệt. Yêu cầu hủy và hoàn tiền cũng có thể được xử lý qua liên hệ hỗ trợ khách hàng chính thức, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Bạn có thể tự hủy đăng ký bất cứ lúc nào. Không cần nhân viên phê duyệt. Việc gia hạn trong tương lai chỉ dừng sau khi nhà cung cấp thanh toán xác nhận việc hủy.",
  "settings.cancelTerms.noApprovalTitle": "Hủy mà không cần phê duyệt:",
  "settings.cancelTerms.paymentBody": "Đối với bản dùng thử trả phí, bản dùng thử bảy ngày yêu cầu phương thức thanh toán khi đăng ký. Trừ khi hủy trong thời hạn hủy dùng thử áp dụng, gói hàng tháng đã chọn sẽ được tính phí tự động sau thời gian dùng thử. Giá, ngày thanh toán đầu tiên và thời hạn hủy cụ thể của nhà cung cấp phải được hiển thị trong quá trình đăng ký. Thanh toán dùng thử được thực hiện qua Stripe.",
  "settings.cancelTerms.paymentTitle": "Phương thức thanh toán và gia hạn tự động:",
  "settings.cancelTerms.remainingBody": "Nếu bạn đã thanh toán cho một kỳ thanh toán, bạn có thể giữ quyền truy cập cho đến ngày đã thanh toán đã xác minh đó. Việc chấm dứt sớm yêu cầu xác nhận phù hợp từ nhà cung cấp và xử lý hoàn tiền áp dụng nếu có. Quyền truy cập dùng thử miễn phí kết thúc theo ngày chấm dứt dùng thử đã được nhà cung cấp xác nhận.",
  "settings.cancelTerms.remainingTitle": "Quyền truy cập còn lại:",
  "settings.cancelTerms.storesBody": "Nếu bạn đăng ký qua Google Play hoặc Apple App Store, đăng ký của bạn sẽ được tính phí và quản lý bởi cửa hàng đó. Bạn có thể cần hủy trực tiếp trong mục đăng ký của cùng tài khoản Google hoặc Apple đã dùng để đăng ký. Việc hủy một đăng ký trang web riêng, gỡ cài đặt ứng dụng này hoặc yêu cầu xóa tài khoản Luminous StockHaven không tự động hủy đăng ký được tính phí qua cửa hàng. Kiểm tra biên lai mua hàng của bạn để xác nhận ai đang tính phí bạn.",
  "settings.cancelTerms.storesTitle": "Đăng ký Google Play và Apple App Store (nếu bạn đăng ký qua cửa hàng):",
  "settings.cancelTerms.title": "Điều khoản và điều kiện hủy",
  "settings.cancelTerms.trialBody": "Bản dùng thử bảy ngày chỉ có thể được sử dụng một lần cho mỗi khách hàng đủ điều kiện. Việc hủy bản dùng thử hoặc đăng ký không cấp thêm bản dùng thử khác; khách hàng quay lại phải chọn đăng ký trả phí.",
  "settings.cancelTerms.trialTitle": "Một lần dùng thử miễn phí:",
  "settings.canceled.endsOn": "Đăng ký này đã bị hủy và kết thúc vào {date}. Bạn giữ toàn quyền truy cập cho đến lúc đó.",
  "settings.delete.checking": "Đang kiểm tra yêu cầu xóa hiện có…",
  "settings.delete.description": "Yêu cầu xóa tài khoản đăng nhập Luminous StockHaven của bạn.",
  "settings.delete.dialogDescription": "Thao tác này yêu cầu xem xét việc xóa tài khoản. Thao tác này không xóa ngay thông tin đăng nhập hoặc hàng tồn kho của bạn, và không hủy bất kỳ đăng ký Stripe nào. Gõ \"{word}\" để xác nhận bạn muốn gửi yêu cầu.",
  "settings.delete.dialogTitle": "Yêu cầu xóa tài khoản",
  "settings.delete.enterDelete": "Nhập {word} để xác nhận",
  "settings.delete.exportFirst": "Hãy xuất hàng tồn kho của bạn trước nếu bạn cần giữ hồ sơ.",
  "settings.delete.intro": "Việc gửi yêu cầu không xóa ngay tài khoản, doanh nghiệp hoặc hàng tồn kho của bạn. Yêu cầu được xem xét riêng trước khi việc xóa có thể hoàn tất. Yêu cầu này không hủy đăng ký Stripe hoặc dừng thanh toán trong tương lai; việc hủy đăng ký phải được xử lý riêng qua nhà cung cấp thanh toán.",
  "settings.delete.keepAccount": "Giữ tài khoản",
  "settings.delete.noExport": "Essentials không có tính năng xuất — hãy ghi lại mọi thứ bạn cần trước khi yêu cầu xóa.",
  "settings.delete.notDeleted": "Tài khoản và dữ liệu của bạn chưa bị xóa bởi yêu cầu này. Thanh toán chưa bị hủy.",
