  "settings.pastDue.body": "Lần thanh toán gần nhất của bạn không thành công. Cập nhật phương thức thanh toán từ trang Nâng cấp — Stripe sẽ tự thử lại theo lịch của mình, và đăng ký của bạn sẽ không bị hủy sớm. Nếu bạn không chắc phải làm gì, hãy liên hệ bộ phận hỗ trợ tại theluminousbookshop@outlook.com.",
