  "settings.title": "Cài đặt",
  "settings.trial.cancelKeeps": "Hủy trong thời gian dùng thử vẫn giữ trọn 7 ngày của bạn — quyền truy cập kết thúc vào {date}, và bạn sẽ không bị tính phí.",
  "staff.access.noSeatBody": "Tài khoản của bạn không có vị trí nhân viên cho doanh nghiệp này, vì vậy hàng tồn kho của doanh nghiệp vẫn đóng. Hãy yêu cầu chủ sở hữu thêm bạn trong mục Nhân viên và vai trò.",
  "staff.access.noSeatTitle": "Doanh nghiệp này không mở cho thông tin đăng nhập của bạn",
  "staff.access.pendingBody": "Doanh nghiệp này có lời mời cho email của bạn chưa được kích hoạt. Hãy yêu cầu chủ sở hữu đặt trạng thái nhân viên của bạn thành đang hoạt động. Không có gì ở đây hiển thị cho đến lúc đó.",
  "staff.access.pendingTitle": "Lời mời của bạn chưa được kích hoạt",
  "staff.access.signOut": "Đăng xuất",
  "staff.access.suspendedBody": "Quản trị viên đã tạm dừng tài khoản nhân viên này cho doanh nghiệp đang hoạt động. Hãy yêu cầu họ đặt bạn trở lại trạng thái đang hoạt động, sau đó đăng nhập lại.",
  "staff.access.suspendedTitle": "Quyền truy cập của bạn đã bị tạm dừng",
  "staff.addFirst": "Thêm nhân viên đầu tiên",
  "staff.addMember": "Thêm nhân viên",
  "staff.emptyBody": "Thêm một người, giao cho họ một vai trò và các quyền đi kèm, và họ sẽ được mời qua email để đăng nhập vào doanh nghiệp này.",
  "staff.emptyTitle": "Chưa có nhân viên",
  "staff.eyebrow": "Đội ngũ",
  "staff.how.p1": "Mỗi thành viên có một vai trò và danh sách quyền riêng, vì vậy bạn có thể bắt đầu từ một vai trò và thay đổi một điều mà không cần tạo vai trò mới. Việc chỉnh sửa một vai trò không viết lại các thành viên đã ở trên vai trò đó — hãy mở một thành viên để áp dụng lại các mặc định của vai trò cho họ.",
  "staff.how.p2": "Vai trò tùy chỉnh là tính năng của Business: Essentials sử dụng năm vai trò tích hợp sẵn (Chủ sở hữu, Quản lý, Nhân viên kho, Nhân viên bán hàng, Người xem).",
  "staff.how.p3": "Lời mời được gửi qua email. Thành viên chỉ có thể đăng nhập sau khi chấp nhận, và việc xóa ai đó khỏi danh sách này không xóa tài khoản ứng dụng của họ.",
  "staff.how.p4": "Cửa hàng là địa điểm mà một người được phân công. Địa điểm được ghi trên thẻ của họ; những gì họ có thể mở vẫn do vai trò và quyền của họ quyết định.",
  "staff.how.p5": "Quyền quyết định mỗi người có thể mở những gì: các mục menu ngoài vai trò của họ bị ẩn, và một địa chỉ bị chặn sẽ hiển thị thông báo “không thuộc vai trò của bạn” thay vì trang. Thay đổi sẽ áp dụng vào lần tiếp theo người đó tải ứng dụng; việc tạm dừng một thành viên sẽ khóa hoàn toàn họ.",
  "staff.how.p6": "Quản trị viên có thể xem và thay đổi tất cả dữ liệu, quản lý người dùng ứng dụng và vai trò, và không bao giờ bị giới hạn bởi vai trò nhân viên. Người không có hồ sơ nhân viên — chủ sở hữu của một doanh nghiệp mới — giữ toàn quyền truy cập.",
  "staff.howTitle": "Cách nhân viên và vai trò hoạt động",
