  "printLib.usbUnavailable": "In qua USB từ trang web cần Chrome trên Android và cáp USB OTG. Trên máy tính để bàn, hãy cắm máy in vào máy tính và dùng nút In — nó sẽ in qua máy in đã cài đặt ở đó. iPhone không thể in qua USB trực tiếp — hãy dùng Wi-Fi bằng AirPrint, hoặc Bluetooth từ ứng dụng di động (sẽ có cùng với ứng dụng di động).",
