  "settings.security.title": "Security & spare keys",
  "settings.security.description": "Set up your spare keys BEFORE you need them: if you ever lose access to your account email, they are how you get your shop back.",
  "settings.security.genericError": "Something went wrong. Please try again.",
  "settings.security.accountEmail": "Account email",
  "settings.security.backupCodesTitle": "Backup codes",
  "settings.security.backupCodesDesc": "One-time spare keys. Print them or write them down and keep them somewhere safe — each one can bring you back once if you lose your email.",
  "settings.security.codesRemaining": "Unused backup codes remaining: {count}",
  "settings.security.generateCodes": "Generate backup codes",
  "settings.security.regenerateCodes": "Generate a fresh set",
  "settings.security.newCodesTitle": "Your new backup codes",
  "settings.security.codesOnceWarning": "These codes are shown only once — we keep only a scrambled copy, so even we cannot show them again. Generating a fresh set cancels every older code.",
  "settings.security.printCodes": "Print these codes",
  "settings.security.backupEmailTitle": "Backup email",
  "settings.security.backupEmailDesc": "A second email address you control. If your main email is ever out of reach, a recovery code can be sent here instead.",
  "settings.security.backupEmailLabel": "Backup email address",
